class NetkitError(Exception):
    """Base class for every error this package raises on purpose."""

class BadAddress(NetkitError, ValueError):
    def __init__(self, text, reason="not an IPv4 address"):
        super().__init__(f"{text!r}: {reason}")
        self.text = text
        self.reason = reason

class ScanTimeout(NetkitError):
    def __init__(self, host, port, seconds):
        super().__init__(f"{host}:{port} did not answer within {seconds}s")
        self.host, self.port, self.seconds = host, port, seconds

def check(addr):
    parts = addr.split(".")
    if len(parts) != 4 or not all(p.isdigit() and int(p) < 256 for p in parts):
        raise BadAddress(addr)
    return addr

for item in ["192.0.2.7", "192.0.2", "192.0.2.256"]:
    try:
        print("ok", check(item))
    except NetkitError as e:
        print(type(e).__name__, "|", e)

