import ipaddress

class ParseError(ValueError):
    def __init__(self, lineno, line, reason):
        super().__init__(f"line {lineno}: {reason}: {line!r}")
        self.lineno = lineno

def parse_host_port(lineno, line):
    host, sep, port = line.strip().rpartition(":")
    if not sep:
        raise ParseError(lineno, line, "missing ':port'")
    try:
        ipaddress.ip_address(host)
    except ValueError:
        raise ParseError(lineno, line, "bad address") from None
    if not port.isdecimal() or not 0 < int(port) < 65536:
        raise ParseError(lineno, line, "bad port")
    return host, int(port)

LINES = ["192.0.2.10:22", "198.51.100.7:80", "203.0.113.5", "300.1.1.1:80", "192.0.2.10:99999", "[2001:db8::1]:443"]

good, bad = [], []
for n, line in enumerate(LINES, 1):
    try:
        good.append(parse_host_port(n, line))
    except ParseError as e:
        bad.append(e)

print(len(good), "parsed,", len(bad), "rejected")
for e in bad:
