"""netparse.py - parse macOS ping output into numbers, safely."""
import logging
import re

log = logging.getLogger(__name__)

REPLY = re.compile(r"^\d+ bytes from (?P<ip>[\d.]+): icmp_seq=(?P<seq>\d+) ttl=(?P<ttl>\d+) time=(?P<ms>[\d.]+) ms$")
TIMEOUT = re.compile(r"^Request timeout for icmp_seq (?P<seq>\d+)$")
SUMMARY = re.compile(r"^(?P<tx>\d+) packets transmitted, (?P<rx>\d+) packets received")


class PingParseError(ValueError):
    def __init__(self, lineno, line, reason):
        super().__init__(f"line {lineno}: {reason}: {line!r}")
        self.lineno, self.line, self.reason = lineno, line, reason


def parse_line(lineno, line):
    """Return ('reply', seq, ms), ('timeout', seq, None), ('summary', tx, rx) or None for ignorable lines."""
    line = line.strip()
    if not line or line.startswith(("PING ", "---", "round-trip")):
        return None
    if m := REPLY.match(line):
        ms = float(m["ms"])
        if ms <= 0:
            raise PingParseError(lineno, line, "non-positive time")
        return ("reply", int(m["seq"]), ms)
    if m := TIMEOUT.match(line):
        return ("timeout", int(m["seq"]), None)
    if m := SUMMARY.match(line):
        return ("summary", int(m["tx"]), int(m["rx"]))
    raise PingParseError(lineno, line, "unrecognised line")


def parse_ping(text):
    """Return a dict with the RTT list, loss count and a list of errors."""
    rtts, lost, errors, summary = [], 0, [], None
    for n, line in enumerate(text.splitlines(), 1):
        try:
            item = parse_line(n, line)
        except PingParseError as e:
            log.warning("%s", e)
            errors.append(e)
            continue
        if item is None:
            continue
        kind, a, b = item
        if kind == "reply":
            rtts.append(b)
        elif kind == "timeout":
            lost += 1
        else:
            summary = (a, b)
    return {"rtts": rtts, "lost": lost, "summary": summary, "errors": errors}
